import{_ as e,o,c as i,a2 as r}from"./chunks/framework.CHeM0PsO.js";const p=JSON.parse('{"title":"Administracao Operacional","description":"","frontmatter":{"status":"rascunho","tipo":"guia-operacao","area":"administracao","atualizado_em":"2026-08-03T00:00:00.000Z"},"headers":[],"relativePath":"planejamento/operacao/administracao-operacional.md","filePath":"planejamento/operacao/administracao-operacional.md","lastUpdated":null}'),s={name:"planejamento/operacao/administracao-operacional.md"};function l(d,a,t,n,c,u){return o(),i("div",null,[...a[0]||(a[0]=[r('<h1 id="administracao-operacional" tabindex="-1">Administracao Operacional <a class="header-anchor" href="#administracao-operacional" aria-label="Permalink to &quot;Administracao Operacional&quot;">​</a></h1><h2 id="quem-usa" tabindex="-1">Quem Usa <a class="header-anchor" href="#quem-usa" aria-label="Permalink to &quot;Quem Usa&quot;">​</a></h2><p>Administradores e responsaveis pela organizacao interna.</p><h2 id="quando-usar" tabindex="-1">Quando Usar <a class="header-anchor" href="#quando-usar" aria-label="Permalink to &quot;Quando Usar&quot;">​</a></h2><p>Para controlar usuarios, cargos, permissoes, calendario, atividades, tarefas e formularios recebidos.</p><h2 id="fluxo-de-usuarios-e-cargos" tabindex="-1">Fluxo de Usuarios e Cargos <a class="header-anchor" href="#fluxo-de-usuarios-e-cargos" aria-label="Permalink to &quot;Fluxo de Usuarios e Cargos&quot;">​</a></h2><ol><li>Acessar <code>/panel/administration</code>.</li><li>Criar ou editar usuarios.</li><li>Associar cargos.</li><li>Revisar permissoes do cargo.</li><li>Desativar usuarios quando necessario.</li></ol><h2 id="fluxo-de-tarefas" tabindex="-1">Fluxo de Tarefas <a class="header-anchor" href="#fluxo-de-tarefas" aria-label="Permalink to &quot;Fluxo de Tarefas&quot;">​</a></h2><ol><li>Criar tarefa com responsavel, prazo e descricao.</li><li>Manter status como <code>in_progress</code> enquanto estiver aberta.</li><li>Mover para <code>in_review</code> quando precisar de revisao.</li><li>Concluir como <code>completed</code> quando entregue.</li><li>Tratar <code>late</code> quando o prazo estourar.</li></ol><h2 id="fluxo-de-calendario-e-atividades" tabindex="-1">Fluxo de Calendario e Atividades <a class="header-anchor" href="#fluxo-de-calendario-e-atividades" aria-label="Permalink to &quot;Fluxo de Calendario e Atividades&quot;">​</a></h2><ol><li>Criar atividade.</li><li>Vincular evento de calendario quando necessario.</li><li>Acompanhar confirmacoes.</li><li>Atualizar informacoes conforme mudancas de data ou responsavel.</li></ol><h2 id="fluxo-de-formularios" tabindex="-1">Fluxo de Formularios <a class="header-anchor" href="#fluxo-de-formularios" aria-label="Permalink to &quot;Fluxo de Formularios&quot;">​</a></h2><ol><li>Consultar formularios recebidos.</li><li>Revisar conteudo.</li><li>Aprovar ou rejeitar.</li><li>Registrar motivo quando aplicavel.</li></ol><h2 id="resultado-esperado" tabindex="-1">Resultado Esperado <a class="header-anchor" href="#resultado-esperado" aria-label="Permalink to &quot;Resultado Esperado&quot;">​</a></h2><ul><li>Usuarios acessam apenas o que seus cargos permitem.</li><li>Tarefas ficam rastreaveis por responsavel e prazo.</li><li>Calendario e atividades refletem compromissos atuais.</li><li>Formularios recebem uma decisao administrativa clara.</li></ul><h2 id="cuidados" tabindex="-1">Cuidados <a class="header-anchor" href="#cuidados" aria-label="Permalink to &quot;Cuidados&quot;">​</a></h2><ul><li>Alteracoes de cargo podem ampliar ou reduzir acesso sensivel.</li><li>Exclusoes e desativacoes precisam ser feitas com criterio.</li><li>Tarefas sem prazo ou responsavel tendem a se perder.</li></ul><h2 id="referencias" tabindex="-1">Referencias <a class="header-anchor" href="#referencias" aria-label="Permalink to &quot;Referencias&quot;">​</a></h2><ul><li><a href="./../modulos/administracao">administracao</a></li><li><a href="./painel-privado">painel-privado</a></li><li><a href="./../modulos/itens-desativados">itens-desativados</a></li></ul>',19)])])}const h=e(s,[["render",l]]);export{p as __pageData,h as default};
